var n={en:`An assistant can draft emails, create support tickets and propose refunds under $50. Executives ask for full automation, but mistakes affect customers and money.`,ua:`Помічник готує листи, створює тікети й пропонує повернення до $50. Керівники хочуть повну автоматизацію, але помилки шкодять клієнтам і фінансам.`};var t={en:[`Classify read-only, reversible and financial actions by risk.`,`Draw permission checks, approvals, audit and idempotency.`,`Write ADR with rollout milestones, monitoring and rollback.`],ua:[`Класифікуй читання, зворотні та фінансові дії за ризиком.`,`Намалюй права, погодження, аудит та ідемпотентність.`,`Напиши ADR з етапами, моніторингом і відкатом.`]};var s=[{en:`Financial actions are authenticated and idempotent.`,ua:`Фінансові дії авторизовані й ідемпотентні.`},{en:`Every side effect links to actor, approval and outcome.`,ua:`Кожна дія пов’язана з виконавцем, погодженням і результатом.`}];var i={scenario:n,tasks:t,checks:s};export{s as checks,i as default,n as scenario,t as tasks};